diff --git a/s2/shapeindex_coding.go b/s2/shapeindex_coding.go
new file mode 100644
index 0000000..cf9524c
--- /dev/null
+++ b/s2/shapeindex_coding.go
@@ -0,0 +1,387 @@
+// Copyright 2023 Google Inc. All rights reserved.
